m=modules[0]
m['intro']='從一個價錢開始，一次只學一件事。先看數字例子，再認識它的名稱；每小節可以反覆看。'
m['lessons']=[
small('先看一個數','一個蘋果賣 8 元。先把價錢記下來。',['我們只記錄價錢：8。','這裡只有一個數字，沒有第二個價錢。'],'像 8 這樣，單獨的一個數，叫純量（scalar）。今天先把它理解成「一個數」就夠了。','8 元的「8」是數值；它不是 8 個格子。',[['8']],'一個價錢，一個數',check=('這裡記錄了幾個價錢？',['1 個','8 個'],0,'只有一個價錢，它的數值剛好是 8。')),
small('把幾個數排在一起','蘋果 8 元、橙 12 元、梨 15 元。',['依「蘋果、橙、梨」的次序，寫成 8、12、15。','把它們排成一排：[8, 12, 15]。','這一排有 3 個數字，每一格記一個價錢。'],'一排數字叫向量（vector）。這個向量的長度是 3，因為它有 3 格。','長度是格子數，不是把 8+12+15 加起來。',[['8','12','15']],'蘋果 → 橙 → 梨：每一格對應一種水果',check=('這一排有幾個數字？',['3 個','35 個'],0,'逐格數：8 是第一格，12 是第二格，15 是第三格，共 3 格。')),
small('再多排一行','星期一和星期二，各記錄三個水果的價錢。',['第一個橫排是星期一：8、12、15。','第二個橫排是星期二：9、11、16。','橫著數有 2 行；直著數有 3 列。'],'像這樣有橫行、有直列的數字表，叫矩陣（matrix）。橫行英文是 row，直列英文是 column。','先看清方向：橫行是橫著的一排；直列是直著的一排。',[['8','12','15'],['9','11','16']],'兩天 × 三種水果。先數橫行，再數直列。',True,('這張表有幾個橫行？',['2 行','3 行'],0,'第一行是星期一，第二行是星期二，所以有 2 行。')),
small('替這張表寫尺寸','沿用剛才的表：2 個橫行，每行 3 格。',['先寫橫行數：2。','再寫直列數：3。','放在括號裡：(2, 3)，讀作「2 行、3 列」。','全部格子是 2×3=6 個。'],'(2, 3) 叫這張表的形狀（shape）。它描述數字怎樣排列；6 則是全部格子的數量。這些數字表在 PyTorch 裡可用張量（tensor）表示；一個數和一排數也可以是 tensor。','把所有價錢改成 0，仍然有 2 行 3 列，所以 shape 不變。',[['0','0','0'],['0','0','0']],'數值變成 0，排列仍然是 (2, 3)。',True,('把這 6 格都改成 0，shape 會變嗎？',['不變，仍是 (2, 3)','變成 (0, 0)'],0,'shape 數的是每個方向有幾格，不是格子裡的價錢。')),
small('同樣 6 個數，可以換排法','把 1、2、3、4、5、6，從 2 行 3 列排成 3 行 2 列。',['原本：第一行 1,2,3；第二行 4,5,6。','改排後：第一行 1,2；第二行 3,4；第三行 5,6。','shape 從 (2,3) 變成 (3,2)，格子數仍是 6。'],'保持數字順序、改變分組排列，叫 reshape。一張表的兩個方向叫兩個軸（axes）；(2,3) 有兩個軸，所以 rank=2。','reshape 不是把表翻轉。翻轉（transpose）會把原本的行變成列，例如 [[1,2,3],[4,5,6]] 轉為 [[1,4],[2,5],[3,6]]。',[['1','2'],['3','4'],['5','6']],'改排後：3 行，每行 2 格。',True,('改排之後，一共還有幾個數？',['6 個','5 個'],0,'只改了排列，3×2 仍是 6 格。')),
small('格子裡放哪種數字？','人數可以記成 3；價錢可以記成 3.5。',['3 是沒有小數部分的整數。','3.5 有小數部分，需要可以表示小數的數字類型。','torch.tensor([3]) 通常用 int64；torch.tensor([3.5]) 在預設設定下通常用 float32。'],'數字的類型叫 dtype。先記兩類：int 常用來表示整數；float 可表示小數。32 和 64 代表使用的 bits，之後遇到記憶體題才計。','同樣一排 3 格，可以放整數，也可以放小數；dtype 和 shape 是兩件事。',[['3','3.5']],'左：人數的整數例子；右：價錢的小數例子',check=('要保留價錢 3.5，應選哪類數字？',['可表示小數的 float','只能表示整數的 int'],0,'float 可保留小數；整數類型不能精確存下這個 3.5。')),
small('數字放在哪裡算？','同一排 [8,12,15]，可以放在 CPU，也可以搬到可用的 GPU。',['原本 x=[8,12,15] 放在 CPU。','若有可用 CUDA GPU，x=x.to("cuda") 可把 tensor 搬過去。','搬的是儲存／計算位置；三個價錢和 shape=(3,) 都不會因此改變。'],'這個位置叫 device。CPU 和 GPU 是兩種計算硬件；CUDA 是課程使用 NVIDIA GPU 時常見的名稱。','GPU 不會自動可用。後面遇到模型時，再一起檢查模型和輸入是否在相容的 device。',check=('把同一排數搬到 GPU，會自動把 8 元改成另一個價錢嗎？',['不會','會'],0,'搬位置不等於更改價錢。')),
small('從一個橫排做乘加','有 2 個蘋果、1 個橙；每個蘋果 4 元，每個橙 2 元。',['蘋果：2×4=8 元。','橙：1×2=2 元。','兩筆加起來：8+2=10 元。','換下一排 [0,3]：0×4+3×2=6 元。'],'把一排數與另一排同樣長的數逐格相乘、再加起來，叫內積（dot product）。矩陣乘法會對每個橫行重複這樣做。','對應位置先相乘，最後才加總；不是把兩排數字直接加在一起。',[['2','1'],['0','3']],'每一行是一張購物單；價錢順序固定為 [4,2]。',True,('第一張購物單 [2,1]，總共多少元？',['10 元','6 元'],0,'2×4+1×2=10。第二張 [0,3] 才是 6 元。')),
small('在表裡找一個數','m=[[8,12,15],[9,11,16]]。想拿第一天的橙價 12。',['人類說「第一行、第二列」。','Python 的位置從 0 開始數，所以第一行是 0，第二列是 1。','m[0,1] 取出 12。','m[:,1] 的 : 表示所有橫行，所以取得兩天的橙價 [12,11]。'],'用位置拿出數字叫索引（indexing）。先寫橫行的位置，再寫直列的位置。','「第一個」在 Python 的索引是 0，第二個才是 1。',[['8','12','15'],['9','11','16']],'Python 橫行索引 0、1；直列索引 0、1、2。',check=('m[0,1] 會拿到哪個數？',['12','9'],0,'0 指第一橫行，1 指第二直列，它們交會的格子是 12。')),
small('一次處理幾個例子','有 4 張 RGB 圖片，每張高 8 格、寬 8 格。',['先數圖片：4 張，叫 batch size。','每張有紅、綠、藍 3 個通道（channels）。','PyTorch 常按「圖片數、通道、高、寬」排列，寫成 (4,3,8,8)。','每張有 3×8×8 個值；4 張共有 4×3×8×8=768 個。'],'batch 是一次交給模型處理的一組例子。B,C,H,W 分別簡寫 batch、channels、height、width。','照片讀進 NumPy 時也常見 (H,W,C)。要換成 (C,H,W)，用 permute 移動軸；reshape 只是重新分組，不能代替換軸。',check=('shape=(4,3,8,8) 中，4 在數甚麼？',['4 張圖片','每張有 4 種顏色'],0,'題設的第一個位置是 batch，也就是這一組有幾張圖片。')),
small('找每條序列的最後一步','兩條序列，每條 3 步，每步 4 個特徵，x.shape=(2,3,4)。',['把三個位置先寫清楚：第 0 軸數序列；第 1 軸數時間步；第 2 軸數特徵。','x[:, -1, :]：第一個 : 保留兩條序列；-1 取每條最後一步；最後 : 保留 4 個特徵。','時間步只選了一步，這個軸被取走，剩下 shape=(2,4)。'],': 表示該軸全部保留；-1 表示該軸的最後一個位置。序列常用 (B,T,F)，即 batch、time、features。','x[-1,:,:] 取的是最後一條序列的全部時間步，並非每條序列的最後一步。',check=('想保留兩條序列，第一個位置應填甚麼？',[':','-1'],0,'第一軸是序列，用 : 保留全部；-1 只拿最後一條。'))
]
